 foreach(['amount'=>'Betrag in Euro','evidence'=>'Grund / Nachweis','legal_basis'=>'Geprüfte steuerliche Grundlage','months'=>'Nutzungsdauer in Monaten']as$key=>$label)if(is_string($post[$key]??null))echo '<dt>'.e($taxText($label)).'</dt><dd>'.e($post[$key]).'</dd>';
 $retained=array_diff_key($post,['csrf'=>true]);
 $recovery=$post===[]?['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$year,'clearings'=>'1']:$taxHome;
 echo '</dl>'.($retained!==[]?'<pre hidden data-tax-retained-fields>'.e(json_encode($retained,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_THROW_ON_ERROR)).'</pre>':'').'<a class="btn btn-outline" href="'.e(url($recovery)).'">'.e($taxText($post===[]?'Zurück zum Bereichsabgleich':'Aktuelle Steuerwerte öffnen')).'</a></section>';if($post!==[]){$originalInputPost=$post;$originalInputText=$taxText;$originalInputOpen=true;require __DIR__.'/balance-original-inputs.php';}return;
}
$actor=\Kulturhus\Verein\Permissions::actor($db,(string)$_SESSION['actor']);$writer=$actor['finance_access']==='write';$board=$writer&&\Kulturhus\Verein\BoardAccess::allowed($db,(string)$_SESSION['actor']);
$values=$s['values'];$income=$s['income'];$money=static fn(int$n):string=>number_format($n/100,2,',','.').' €';
