if($post===[]&&$income!==null)try{$carry=$service->carry($year);}catch(DomainException|JsonException$ex){$carryError=$ex->getMessage();}
$canPrepare=$writer&&$income!==null&&($post!==[]||(($s['carry_current']||$board)&&$carry!==null));
$matches=static fn(string$suffix,string$period='',string$id=''):bool=>$post===[]||(input($post,'action')==='balance-tax-reconciliation-'.$suffix&&($suffix!=='remove'||(input($post,'period')===$period&&input($post,'adjustment_id')===$id)));
$fields=static function(string$suffix,string$period='',string$id='')use($post,$year,$s,$income,$carry):string{
 $same=$post!==[];$source=$income['scope']['review']['clearing']??['revision'=>'','sha256'=>''];$prior=$carry['prior_source']??null;
 $fields=csrf().hidden('action','balance-tax-reconciliation-'.$suffix).hidden('balance_year',$same?input($post,'balance_year'):(string)$year).hidden('version',$same?input($post,'version'):(string)$s['version']).hidden('income_sha256',$same?input($post,'income_sha256'):($income['sha256']??''));
 foreach(['tax_clearing_revision'=>(string)$source['revision'],'tax_clearing_sha256'=>$source['sha256'],'tax_prior_year'=>isset($prior['year'])?(string)$prior['year']:'','tax_prior_revision'=>isset($prior['revision'])?(string)$prior['revision']:'','tax_prior_sha256'=>$prior['sha256']??'']as$key=>$value)$fields.=hidden($key,$same?input($post,$key):$value);
 if(in_array($suffix,['value','off-balance'],true))$fields.=hidden('tax_request_key',$same?input($post,'tax_request_key'):bin2hex(random_bytes(16)));
 if($suffix==='remove')$fields.=hidden('period',$period).hidden('adjustment_id',$id);return $fields;
};
$finish=static function(string$button)use($post,$taxText):string{return '<label>'.e($taxText('Grund / Nachweis')).'<input class="form-control" name="evidence" maxlength="1000" value="'.e(input($post,'evidence')).'" required></label><label class="check"><input class="check" type="checkbox" name="reviewed" value="1" required'.(input($post,'reviewed')==='1'?' checked':'').'>'.e($taxText('Angaben anhand der Belege geprüft.')).'</label>'.hidden('tax_reconciliation_form_complete','1').'<button class="btn btn-solid theme-primary">'.e($taxText($button)).'</button>';};
$select=static function(string$name,string$label,array$choices)use($post,$taxText):string{
 $old=input($post,$name);$out='<label>'.e($taxText($label)).'<select class="form-control" name="'.e($name).'" required><option value="">'.e($taxText('Bitte auswählen')).'</option>';
 if($old!==''&&!array_key_exists($old,$choices))$out.='<option selected value="'.e($old).'">'.e($taxText('Bisherige Auswahl prüfen:')).' '.e($old).'</option>';
 foreach($choices as$key=>$text)$out.='<option value="'.e($key).'"'.($old===(string)$key?' selected':'').'>'.e($text).'</option>';return $out.'</select></label>';
};
$chart=$income['scope']['source']['accounts']??[];$accountChoices=[];foreach($chart as$id=>$account)$accountChoices[$id]=trim($account['skr_code'].' '.$account['name']);
$sourceLabels=[];foreach(array_values($income['scope']['source']['entries']??[])as$position=>$entry){$label=$taxText('Buchung').' '.($position+1).' · '.implode('.',array_reverse(explode('-',$entry['date']))).' · '.mb_substr($entry['description'],0,100);foreach($entry['lines']as$i=>$line)$sourceLabels['journal:'.$entry['id'].':'.$i]=$label.' · '.$taxText('Zeile').' '.($i+1);}
foreach($values['valuation']['current_adjustments']??[]as$position=>$entry)foreach($entry['lines']as$i=>$line)$sourceLabels['tax:'.$entry['id'].':'.$i]=$taxText('Steuerkorrektur').' '.($position+1).' · '.mb_substr($entry['reason'],0,100).' · '.$taxText('Zeile').' '.($i+1);
?>
<?php if($post!==[]){$originalInputPost=$post;$originalInputText=$taxText;$originalInputUnits=$income['scope']['allocation']['units']??[];$originalInputAccounts=$chart;$originalInputSources=$sourceLabels;$originalInputTargets=[];foreach($values['review']??[]as$originalRecoveryType=>$originalRecoveryRows)if(is_array($originalRecoveryRows))foreach($originalRecoveryRows as$originalRecoveryKey=>$originalRecoveryRow)if(is_array($originalRecoveryRow))$originalInputTargets[$originalRecoveryType][$originalRecoveryRow['id']??$originalRecoveryKey]=$originalRecoveryRow;$originalInputAssets=$income['scope']['source']['asset_schedule']['items']??[];$originalInputOpen=!$writer;require __DIR__.'/balance-original-inputs.php';} ?>
