<?php if($post!==[]): ?><section class="card" role="status"><h2><?= e($taxText('Formularstand')) ?></h2><p><?= e($taxText('Diese Eingaben gehören zum damals geöffneten Steuerwerte-Abgleich. Aktuelle Steuerwerte getrennt prüfen.')) ?></p><a class="btn btn-outline" href="<?= e(url($taxHome)) ?>"><?= e($taxText('Aktuelle Steuerwerte öffnen')) ?></a></section><?php endif ?>
<section class="card"><h1><?= e($taxText('Steuerliches Ergebnis')) ?> · <?= $year ?></h1>
<p><a href="<?= e(url(['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$year,'clearings'=>'1'])) ?>"><?= e($taxText('Zurück zum Bereichsabgleich')) ?></a></p>
<p role="status"><strong><?= e($taxText($post!==[]?'Ungespeicherte Eingaben – gespeicherten Nachweis getrennt prüfen':($s['current_approval']?'Steuerwerte geprüft':'Prüfung der Steuerwerte offen'))) ?></strong></p>
<?php if(!$s['source_current']): ?><p role="alert"><?= e($taxText('Zuerst den aktuellen Bereichsabgleich prüfen. Danach die Steuerwerte erneut berechnen und bestätigen.')) ?></p><?php endif ?>
<?php if(!$s['carry_current']): ?><p role="alert"><?= e($taxText('Die Prüfung des Vorjahres wurde geändert. Der Vorstand muss die übernommenen Steuerwerte erneut prüfen.')) ?></p><?php endif ?>
<?php if($carryError!==''): ?><p role="alert"><?= e($taxText($carryError)) ?></p><?php endif ?>
<?php if($income): ?><p><?= e($taxText('Ergebnis aller steuerpflichtigen Betriebe vor Steuerkorrekturen:')) ?> <strong><?= $money($income['result']['taxable_book_cents']) ?></strong></p><?php endif ?>
<p><?= e($taxText('Die Originalbuchungen bleiben erhalten. Hier wird noch nichts an das Finanzamt gesendet.')) ?></p></section>
<?php if($values):require __DIR__.'/balance-tax-reconciliation-values.php';endif ?>
<?php if($canPrepare&&$matches('prepare')): ?><section class="card"><h2><?= e($taxText($values?'Berechnung aktualisieren':'Steuerwerte vorbereiten')) ?></h2><form method="post" data-tax-operation="prepare" <?= $post!==[]?'data-unsaved-changes':'' ?>><?= $fields('prepare') ?><p><?= e($taxText($values?'Vorhandene Korrekturen bleiben erhalten.':'Die geprüften Buchwerte werden übernommen. Abweichende Steuerwerte können unten ergänzt werden.')) ?></p><?= $finish($values?'Neu berechnen':'Berechnung speichern') ?></form></section><?php endif ?>
<?php if($values): ?><section class="card"><details <?= input($post,'action')==='balance-tax-reconciliation-remove'?'open':'' ?>><summary><?= e($taxText('Erfasste Korrekturen')) ?></summary>
<?php foreach(['opening_adjustments'=>'Unterschiede am Jahresanfang','current_adjustments'=>'Bewertungsänderungen im Jahr','off_balance_adjustments'=>'Korrekturen außerhalb der Bilanz','asset_tax_plans'=>'Abweichende Nutzungsdauer']as$period=>$label): ?><h3><?= e($taxText($label)) ?></h3>
<?php if(!$values['review'][$period]): ?><p><?= e($taxText('Keine.')) ?></p><?php else:foreach($values['review'][$period]as$key=>$row):$id=$period==='asset_tax_plans'?$key:$row['id'];require __DIR__.'/balance-tax-reconciliation-adjustment.php'; ?>
<?php if($canPrepare&&$period!=='opening_adjustments'&&$matches('remove',$period,$id)): ?><form method="post" aria-label="<?= e($taxText('Diese Korrektur aufheben').' · '.$row['reason']) ?>" data-tax-operation="remove" <?= $post!==[]?'data-unsaved-changes':'' ?>><?= $fields('remove',$period,$id).$finish('Diese Korrektur aufheben') ?></form><?php endif ?>
<?php endforeach;endif;endforeach ?></details></section><?php endif ?>
<?php if($canPrepare&&($matches('value')||$matches('off-balance')||$matches('asset'))): ?><section class="card"><details <?= $post!==[]?'open':'' ?>><summary><?= e($taxText('Für die Buchhaltung: Korrekturen erfassen')) ?></summary>
