<form method="post" data-tax-operation="value" <?= $post!==[]?'data-unsaved-changes':'' ?>><?= $fields('value').$select('debit_account','Sollkonto',$accountChoices).$select('credit_account','Habenkonto',$accountChoices) ?><label><?= e($taxText('Betrag in Euro')) ?><input class="form-control" name="amount" inputmode="decimal" value="<?= e(input($post,'amount')) ?>" placeholder="12,50" required></label><?= $finish('Wertänderung erfassen') ?></form><?php endif ?>
<?php if($matches('off-balance')):
 $sources=$values&&$s['source_current']?\Kulturhus\Verein\BalanceClubTaxReconciliation::correctionSources($values):[];
 if(!$values&&$income)foreach($income['lines']as$key=>$line){if($line['sphere']!=='4')continue;$a=$chart[$line['account']];$sources['journal:'.$key]=['account'=>$line['account'],'cents'=>($a['group']==='expense'?1:-1)*($line['debit_cents']-$line['credit_cents'])];}
 $usedSources=[];foreach($values['off_balance']['entries']??[]as$correction)foreach($correction['sources']as$key=>$amount)$usedSources[$key]=($usedSources[$key]??0)+$amount;
 $sourceChoices=[];foreach($sources as$key=>$line){$remaining=$line['cents']-($usedSources[$key]??0);if($remaining===0)continue;$available=(isset($usedSources[$key])?$taxText('noch').' ':'').$money($remaining);$sourceChoices[$key]=isset($line['asset_id'])?$line['name'].' · '.$taxText('Abschreibung (steuerlich)').' · '.$available:($values['valuation']['accounts'][$line['account']]['name']??$chart[$line['account']]['name']).' · '.$available.' · '.($sourceLabels[$key]??$taxText('Zugehörige Buchung'));}
 ?><h3><?= e($taxText('Hinzurechnung oder Kürzung')) ?></h3><form method="post" data-tax-operation="off-balance" <?= $post!==[]?'data-unsaved-changes':'' ?>><?= $fields('off-balance').$select('correction_kind','Steuerliche Korrektur',['non_deductible_expense'=>$taxText('Nicht abziehbare Ausgabe hinzurechnen'),'tax_exempt_income'=>$taxText('Steuerfreie Einnahme abziehen')]).$select('source_line','Beleg oder Gegenstand',$sourceChoices) ?><label><?= e($taxText('Davon zu korrigieren · Euro')) ?><input class="form-control" name="amount" inputmode="decimal" value="<?= e(input($post,'amount')) ?>" placeholder="12,50" required></label><label><?= e($taxText('Geprüfte steuerliche Grundlage')) ?><input class="form-control" name="legal_basis" maxlength="1500" value="<?= e(input($post,'legal_basis')) ?>" required></label><?= $finish('Steuerkorrektur erfassen') ?></form><?php endif ?>
<?php $assetChoices=[];foreach($income['scope']['source']['asset_schedule']['items']??[]as$id=>$asset)if($asset['sphere']==='4'&&($asset['method']??'linear_monthly')==='linear_monthly'&&!isset($asset['gwg'])&&!isset($asset['degressive'])&&!isset($asset['sphere_change']))$assetChoices[$id]=($asset['name']??$asset['receipt_number']??$id).' · '.$asset['skr_code'].' · '.implode('.',array_reverse(explode('-',$asset['acquired_on'])));
 if($matches('asset')&&($assetChoices||input($post,'action')==='balance-tax-reconciliation-asset')): ?><h3><?= e($taxText('Abweichende steuerliche Nutzungsdauer')) ?></h3><form method="post" data-tax-operation="asset" <?= $post!==[]?'data-unsaved-changes':'' ?>><?= $fields('asset').$select('asset','Gegenstand',$assetChoices) ?><label><?= e($taxText('Nutzungsdauer in Monaten')) ?><input class="form-control" name="months" type="number" min="12" max="1200" step="12" value="<?= e(input($post,'months')) ?>" required></label><?php $expenseChoices=[];foreach($chart as$id=>$a)if($a['group']==='expense')$expenseChoices[$id]=$accountChoices[$id]; ?><?= $select('depreciation_account','Abschreibungskonto',$expenseChoices).$finish('Steuerliche Nutzungsdauer übernehmen') ?></form><?php endif ?>
</details></section><?php endif ?>
